def minSecurityThreshold(n: int, sector_keys: list[int], roads: list[list[int]], source: int, target: int, k: int, required_sectors: int) -> int:
    from collections import deque
    adj = [[] for _ in range(n)]
    weights = [0]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))
        weights.append(w)

    weights = sorted(list(set(weights)))

    start_mask = 0
    if sector_keys[source] != -1:
        start_mask = 1 << sector_keys[source]

    def can(threshold):
        dist = {}
        q = deque()
        dist[(source, start_mask)] = 0
        q.append((source, start_mask, 0))

        while q:
            u, mask, d = q.popleft()
            if d > dist.get((u, mask), float('inf')):
                continue
            if u == target and (mask & required_sectors) == required_sectors:
                return True

            for v, w in adj[u]:
                nxt_mask = mask
                if sector_keys[v] != -1:
                    nxt_mask |= (1 << sector_keys[v])
                cost = 1 if w > threshold else 0
                nxt_d = d + cost
                if nxt_d <= k and nxt_d < dist.get((v, nxt_mask), float('inf')):
                    dist[(v, nxt_mask)] = nxt_d
                    if cost == 0:
                        q.appendleft((v, nxt_mask, nxt_d))
                    else:
                        q.append((v, nxt_mask, nxt_d))
        return False

    lo = 0
    hi = len(weights) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if can(weights[mid]):
            ans = weights[mid]
            hi = mid - 1
        else:
            lo = mid + 1

    return ans
